package com.ashkan.hotel;
import com.sun.net.httpserver.*;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.time.Duration;
public final class HotelEdgeGatewaySmokeTest {
 public static void main(String[] args)throws Exception{
  HttpServer upstream=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);upstream.createContext("/health",x->{byte[] b="{\"status\":\"UP\"}".getBytes();x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});upstream.createContext("/api/v2/bookings",x->{byte[] b="{\"v2\":true}".getBytes();x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});upstream.createContext("/api/v1/bookings",x->{byte[] b=("{\"method\":\""+x.getRequestMethod()+"\",\"role\":\""+x.getRequestHeaders().getFirst("X-Authenticated-Role")+"\"}").getBytes();x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});upstream.start();
  try{ServiceRegistry registry=new ServiceRegistry().register("booking",URI.create("http://127.0.0.1:"+upstream.getAddress().getPort()+"/"));HotelEdgeGateway gateway=new HotelEdgeGateway(0,registry,new JwtTokenService("0123456789abcdef0123456789abcdef",3600),new AuthService(Files.createTempDirectory("edge-auth")));
   try(gateway){gateway.start();HttpClient c=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();String base="http://127.0.0.1:"+gateway.port();HttpResponse<String> denied=c.send(HttpRequest.newBuilder(URI.create(base+"/api/bookings")).GET().build(),HttpResponse.BodyHandlers.ofString());if(denied.statusCode()!=401)throw new AssertionError("anonymous request allowed");
    String body="{\"username\":\"Receptionist\",\"password\":\"desk123\"}";HttpResponse<String> login=c.send(HttpRequest.newBuilder(URI.create(base+"/auth/login")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());if(login.statusCode()!=200)throw new AssertionError("login failed: "+login.body());String token=login.body().replaceAll(".*\\\"access_token\\\":\\\"([^\\\"]+)\\\".*","$1");
    HttpResponse<String> proxied=c.send(HttpRequest.newBuilder(URI.create(base+"/api/bookings")).header("Authorization","Bearer "+token).GET().build(),HttpResponse.BodyHandlers.ofString());if(proxied.statusCode()!=200||!proxied.body().contains("Receptionist")||proxied.headers().firstValue("X-Content-Type-Options").isEmpty()||proxied.headers().firstValue("X-Request-Id").isEmpty())throw new AssertionError("proxy failed: "+proxied.body());
    HttpResponse<String> v2=c.send(HttpRequest.newBuilder(URI.create(base+"/api/v2/bookings?page=1")).header("Authorization","Bearer "+token).GET().build(),HttpResponse.BodyHandlers.ofString());if(v2.statusCode()!=200||!v2.body().contains("v2"))throw new AssertionError("v2 proxy failed: "+v2.body());
    HttpResponse<String> paymentWrite=c.send(HttpRequest.newBuilder(URI.create(base+"/api/v2/payments")).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{} ")).build(),HttpResponse.BodyHandlers.ofString());if(paymentWrite.statusCode()!=403)throw new AssertionError("receptionist payment write allowed");
    HttpResponse<String> forbidden=c.send(HttpRequest.newBuilder(URI.create(base+"/api/bookings/1")).header("Authorization","Bearer "+token).DELETE().build(),HttpResponse.BodyHandlers.ofString());if(forbidden.statusCode()!=403)throw new AssertionError("role policy failed");
   }
  }finally{upstream.stop(0);}System.out.println("HotelEdgeGatewaySmokeTest passed");
 }
}
